// Generated sites for the calibration of the template gate (V3-14): one-page sites of one niche built from section
// variants (the same section types in the same order — the hard case, as the composer's PAGE_SECTIONS gives every site
// of a niche), rendered as static HTML with the composer's DOM frame (header, <main id="main"> with a <div> per body
// section, footer). A near-duplicate keeps every variant and changes the texts, the palette (a dark one included), the
// fonts and the spacing; a different site changes the variants. Everything is generated by code from a seed.
import type { TemplateSite } from "@wizard/gates";

export const SECTION_ORDER = [
  "header",
  "hero",
  "services",
  "about",
  "testimonials",
  "faq",
  "form",
  "footer",
] as const;
export type FixtureSection = (typeof SECTION_ORDER)[number];

/** Variants of each section type with their layout family (as the ui-kit library tags them). */
export const VARIANTS: Readonly<Record<FixtureSection, Readonly<Record<string, string>>>> = {
  header: { bar: "bar", centered: "centered", "cta-right": "split" },
  hero: { split: "split", centered: "centered", "full-bleed": "full-bleed", editorial: "editorial" },
  services: { cards: "grid", list: "list", zigzag: "split", tiles: "columns" },
  about: { "split-image": "split", stats: "columns", quote: "typographic" },
  testimonials: { cards: "card", single: "centered", wall: "collage" },
  faq: { accordion: "list", "two-col": "split" },
  form: { centered: "centered", split: "split" },
  footer: { columns: "columns", simple: "bar", band: "band" },
};

export type Variants = Record<FixtureSection, string>;

export interface Look {
  bg: string;
  fg: string;
  muted: string;
  accent: string;
  band: string;
  font: string;
  /** Base spacing unit, px. */
  unit: number;
}

