/** A small deterministic generator (mulberry32). */
export function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const WORDS =
  "запись приём врач клиника лечение зубы консультация чистка имплант брекеты улыбка гигиена диагностика снимок пломба отбеливание скидка семья ребёнок забота спокойно быстро удобно рядом вечером субботу гарантия опыт отзыв".split(
    " ",
  );

function words(r: () => number, min: number, max: number): string {
  const n = min + Math.floor(r() * (max - min + 1));
  const out: string[] = [];
  for (let i = 0; i < n; i++) out.push(WORDS[Math.floor(r() * WORDS.length)] as string);
  const s = out.join(" ");
  return s.charAt(0).toUpperCase() + s.slice(1);
}

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;");

/** A gray «photo» box of the given aspect (the gate serves every photo as the same neutral image). */
const photo = (ratio: string, extra = "") => `<div class="ph" style="aspect-ratio:${ratio};${extra}"></div>`;

function section(type: FixtureSection, variant: string, r: () => number): string {
  const t = (a: number, b: number) => esc(words(r, a, b));
  const btn = (primary = true) => `<a class="btn${primary ? "" : " ghost"}" href="#form">${t(1, 3)}</a>`;
  const nav = () => Array.from({ length: 5 }, () => `<a href="#">${t(1, 1)}</a>`).join("");
  switch (`${type}:${variant}`) {
    case "header:bar":
      return `<header class="wrap row between pad-s"><b class="logo">${t(1, 2)}</b><nav class="row gap nav">${nav()}</nav>${btn()}</header>`;
    case "header:centered":
      return `<header class="wrap col center pad-s"><b class="logo big">${t(1, 2)}</b><nav class="row gap nav">${nav()}</nav></header>`;
    case "header:cta-right":
      return `<header class="wrap row between pad-s"><b class="logo">${t(1, 2)}</b><div class="row gap"><span>+7 843 200-40-50</span>${btn()}<button class="burger" aria-label="Меню">≡</button></div></header>`;
    case "hero:split":
      return `<section class="wrap grid2 pad-l"><div class="col"><h1>${t(4, 8)}</h1><p>${t(14, 26)}</p><div class="row gap">${btn()}${btn(false)}</div></div>${photo("4/3")}</section>`;
    case "hero:centered":
      return `<section class="wrap col center pad-xl narrow"><h1 class="huge">${t(3, 6)}</h1><p>${t(12, 22)}</p>${btn()}</section>`;
    case "hero:full-bleed":
      return `<section class="bleed"><div class="ph cover"></div><div class="over wrap"><h1 class="inv">${t(3, 7)}</h1><p class="inv">${t(10, 18)}</p>${btn()}</div></section>`;
    case "hero:editorial":
      return `<section class="wrap pad-l"><h1 class="mega">${t(2, 4)}</h1><div class="grid3"><p>${t(16, 28)}</p><span></span>${photo("3/2")}</div></section>`;
    case "services:cards":
      return `<section class="wrap pad-l"><h2>${t(2, 4)}</h2><div class="grid3">${Array.from({ length: 6 }, () => `<div class="card"><i class="ico"></i><h3>${t(2, 3)}</h3><p>${t(8, 16)}</p></div>`).join("")}</div></section>`;
    case "services:list":
      return `<section class="wrap pad-l"><h2>${t(2, 4)}</h2><ul class="rows">${Array.from({ length: 6 }, () => `<li class="grid2 line"><h3>${t(2, 3)}</h3><p>${t(10, 18)}</p></li>`).join("")}</ul></section>`;
    case "services:zigzag":
      return `<section class="wrap pad-l"><h2>${t(2, 4)}</h2>${Array.from({ length: 3 }, (_, i) => `<div class="grid2 zig">${i % 2 ? "" : photo("16/10")}<div><h3>${t(2, 4)}</h3><p>${t(16, 26)}</p></div>${i % 2 ? photo("16/10") : ""}</div>`).join("")}</section>`;
    case "services:tiles":
      return `<section class="band pad-l"><div class="wrap"><h2 class="c">${t(2, 4)}</h2><div class="grid4">${Array.from({ length: 8 }, () => `<div class="tile"><i class="ico"></i><h3>${t(1, 2)}</h3></div>`).join("")}</div></div></section>`;
    case "about:split-image":
      return `<section class="wrap grid2 pad-l">${photo("1/1")}<div><h2>${t(3, 5)}</h2><p>${t(30, 50)}</p><p>${t(20, 30)}</p></div></section>`;
    case "about:stats":
      return `<section class="band pad-l"><div class="wrap"><h2>${t(3, 5)}</h2><div class="grid4">${Array.from({ length: 4 }, () => `<div><b class="num">${Math.floor(r() * 900 + 10)}</b><p>${t(2, 4)}</p></div>`).join("")}</div></div></section>`;
    case "about:quote":
      return `<section class="wrap col center pad-xl narrow"><blockquote class="q">${t(16, 26)}</blockquote><p>${t(2, 3)}</p></section>`;
    case "testimonials:cards":
      return `<section class="wrap pad-l"><h2>${t(2, 3)}</h2><div class="grid3">${Array.from({ length: 3 }, () => `<figure class="card"><blockquote>${t(14, 26)}</blockquote><figcaption>${t(2, 2)}</figcaption></figure>`).join("")}</div></section>`;
    case "testimonials:single":
      return `<section class="band pad-xl"><div class="wrap col center narrow"><i class="ava"></i><blockquote class="q">${t(18, 30)}</blockquote><p>${t(2, 2)}</p></div></section>`;
    case "testimonials:wall":
      return `<section class="wrap pad-l"><h2 class="c">${t(2, 3)}</h2><div class="masonry">${Array.from({ length: 7 }, () => `<figure class="card"><blockquote>${t(8, 34)}</blockquote><figcaption>${t(2, 2)}</figcaption></figure>`).join("")}</div></section>`;
    case "faq:accordion":
      return `<section class="wrap pad-l narrow"><h2>${t(2, 3)}</h2><ul class="rows">${Array.from({ length: 6 }, () => `<li class="row between line"><h3>${t(4, 8)}</h3><span>+</span></li>`).join("")}</ul></section>`;
    case "faq:two-col":
      return `<section class="wrap grid2 pad-l"><div><h2>${t(2, 3)}</h2><p>${t(10, 16)}</p></div><dl>${Array.from({ length: 4 }, () => `<dt><b>${t(4, 8)}</b></dt><dd>${t(12, 20)}</dd>`).join("")}</dl></section>`;
    case "form:centered":
      return `<section class="band pad-l" id="form"><div class="wrap col center narrow"><h2>${t(2, 4)}</h2><p>${t(8, 14)}</p><form class="card col"><label>${t(1, 1)}<input></label><label>${t(1, 1)}<input></label><button class="btn">${t(1, 2)}</button></form></div></section>`;
    case "form:split":
      return `<section class="wrap grid2 pad-l" id="form"><div><h2>${t(3, 5)}</h2><p>${t(14, 22)}</p></div><form class="col"><label>${t(1, 1)}<input></label><label>${t(1, 1)}<input></label><label>${t(1, 1)}<textarea></textarea></label><button class="btn">${t(1, 2)}</button></form></section>`;
    case "footer:columns":
      return `<footer class="wrap grid4 pad-l">${Array.from({ length: 4 }, () => `<div class="col"><b>${t(1, 2)}</b>${Array.from({ length: 4 }, () => `<a href="#">${t(1, 2)}</a>`).join("")}</div>`).join("")}</footer>`;
    case "footer:simple":
      return `<footer class="wrap row between pad-s"><b class="logo">${t(1, 2)}</b><span>© 2026 ${t(1, 2)}</span></footer>`;
    case "footer:band":
      return `<footer class="dark pad-xl"><div class="wrap col center"><h2 class="inv">${t(3, 5)}</h2>${btn()}<nav class="row gap nav inv">${nav()}</nav></div></footer>`;
    default:
      throw new Error(`no variant ${type}:${variant}`);
  }
}

