export interface FixtureSite {
  name: string;
  variants: Variants;
  html: string;
  site: TemplateSite;
}

/** A one-page site: the given variants, texts from `textSeed`, the look. */
export function fixtureSite(name: string, variants: Variants, textSeed: number, look: Look): FixtureSite {
  const r = rng(textSeed);
  const parts = SECTION_ORDER.map((t) => ({ t, html: section(t, variants[t], r) }));
  const body = parts
    .filter((p) => p.t !== "header" && p.t !== "footer")
    .map((p) => `<div id="${p.t}">${p.html}</div>`)
    .join("\n");
  const html = `<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><style>${css(look)}</style></head><body><div id="root">${parts[0]?.html}<main id="main">${body}</main>${parts[parts.length - 1]?.html}</div></body></html>`;
  return {
    name,
    variants,
    html,
    site: {
      pages: [
        {
          route: "/",
          sections: SECTION_ORDER.map((t) => ({ id: t, type: t, pattern: `${t}-${variants[t]}` })),
        },
      ],
    },
  };
}

/** Variants picked by a seed (each section type independently). */
export function randomVariants(seed: number): Variants {
  const r = rng(seed);
  const out = {} as Variants;
  for (const t of SECTION_ORDER) {
    const ids = Object.keys(VARIANTS[t]);
    out[t] = ids[Math.floor(r() * ids.length)] as string;
  }
  return out;
}

/** Variants that differ from `base` in every section type that has another variant. */
export function otherVariants(base: Variants, seed: number): Variants {
  const r = rng(seed);
  const out = {} as Variants;
  for (const t of SECTION_ORDER) {
    const ids = Object.keys(VARIANTS[t]).filter((v) => v !== base[t]);
    out[t] = ids[Math.floor(r() * ids.length)] as string;
  }
  return out;
}

/** `base` with `k` of its section types (picked by the seed) in another variant. */
export function mixVariants(base: Variants, k: number, seed: number): Variants {
  const r = rng(seed);
  const other = otherVariants(base, seed);
  const types = [...SECTION_ORDER].sort(() => r() - 0.5).slice(0, k);
  const out = { ...base };
  for (const t of types) out[t] = other[t];
  return out;
}

/** Layout lookup of the fixture patterns (`<type>-<variant>`). */
export function fixtureLookup(
  id: string,
): { sectionType: string; layout: string; variant: string } | undefined {
  for (const t of SECTION_ORDER)
    if (id.startsWith(`${t}-`)) {
      const variant = id.slice(t.length + 1);
      const layout = VARIANTS[t][variant];
      return layout ? { sectionType: t, layout, variant } : undefined;
    }
  return undefined;
}
